class ParenGroupSplitter {
  static List<String> splitParenGroups(String input) {
    final List<int> openIndices = <int>[];
    final List<int> closeIndices = <int>[];

    int balance = 0;

    for (var i = 0; i < input.length; ++i) {
      if (input[i] == '(') {
        openIndices.add(i);
        balance++;
      } else if (input[i] == ')') {
        closeIndices.add(i);
        balance--;
      }
    }

    if (balance != 0) {
      stdout.write("Unbalanced parentheses");
      return [];
    }

    final List<String> groups = <String>[];
    var currentPos = 0;

    while (openIndices.isNotEmpty && closeIndices.isNotEmpty) {
      final startIndex = openIndices.removeAt(0);
      final endIndex = closeIndices.removeAt(0);

      String content = '';
      bool hasContent = false;

      for (var i = startIndex + 1; i < endIndex; ++i) {
        if (input[i] != '(' && input[i] != ')') {
          content += input[i];
          hasContent = true;
        }
      }

      if (!hasContent) {
        groups.add(input.substring(startIndex, endIndex + 1));
      } else {
        groups.add(input.substring(startIndex, startIndex + 1));
        groups.add(content);
        groups.add(input.substring(endIndex, endIndex + 1));
      }

      currentPos = endIndex + 1;
    }

    // Handle any trailing characters after last parenthesis
    if (currentPos < input.length) {
      groups.add(input.substring(currentPos));
    }

    return groups;
  }
}

// Example usage:
void main() {
  final testInput = "((a)(b))";
  final result = ParenGroupSplitter.splitParenGroups(testInput);
  print(result);
}
