import 'dart:math';

bool correctBracketing(String brackets) {
  if (brackets.isEmpty) return true;

  final n = brackets.length;
  final stack = <int>[];

  for (var i = 0; i < n; i++) {
    final char = brackets[i];

    if (char == '(' || char == '[' || char == '{') {
      stack.add(_getBraceIndex(char));
    } else {
      if (stack.isEmpty) return false;

      final top = _getBraceType(stack.removeLast());
      if (_isMatchingPair(top, char)) continue;
      return false;
    }
  }

  return stack.isEmpty;
}

int _getBraceIndex(String brace) {
  switch (brace) {
    case '(':
      return 0;
    case '[':
      return 1;
    case '{':
      return 2;
    default:
      throw ArgumentError('Invalid brace character');
  }
}

String _getBraceType(int index) {
  switch (index) {
    case 0:
      return '(';
    case 1:
      return '[';
    case 2:
      return '{';
    default:
      throw ArgumentError('Invalid brace index');
  }
}

bool _isMatchingPair(String open, String close) {
  return (open == '(' && close == ')') ||
         (open == '[' && close == ']') ||
         (open == '{' && close == '}');
}
