    if (s[i] == '(') {
      var j = findMatchingParenthesis(s, i + 1);
      if (j != null && j < n) {
        String inner = s.substring(i + 1, j);
        int lengthInner = inner.length;
        List<String> parts = [];
        Stack<String> stack = Stack();
        bool inQuote = false;
        for (var c in inner.split('')) {
          if (c == '"') {
            inQuote = !inQuote;
          } else if (c == ',' && !inQuote) {
            stack.add('');
            parts.add(stack.removeLast());
            continue;
          }
          if (!stack.isEmpty && c == ')') {
            stack.last += ')';
            parts.add(stack.removeLast());
          } else if (!stack.isEmpty && c == '(') {
            stack.last += '(';
            continue;
          } else if (c == ')' || c == '(') {
            stack.add(c.toString());
          } else {
            stack.last += c;
          }
        }

        while (stack.isNotEmpty) {
          parts.add(stack.removeLast());
        }

        int totalLength = 0;
        for (var part in parts) {
          totalLength += part.length;
        }

        if (totalLength > lengthInner) {
          return '';
        }

        int k = 0;
        for (var part in parts) {
          int lenPart = part.length;
          for (int m = 0; m < lenPart; m++) {
            res[k++] = part.codeUnitAt(m);
          }
        }
      }
    }
  }
  return String.fromCharCodes(res).split('').join('');
}

