List<int> minPath(List<List<int>> grid, int k) {
  if (grid == null || grid.isEmpty || grid[0].isEmpty) return [];

  final rows = grid.length;
  final cols = grid[0].length;
  final directions = [1, 3];

  // Initialize a priority queue for Dijkstra's algorithm
  final pq = PriorityQueue<PriorityNode>();
  final visited = List.generate(rows * cols, (_) => false);
  final dist = List.generate(rows * cols, (_) => -1);

  final startRow = 0;
  final startCol = 0;
  final startIndex = startRow * cols + startCol;

  dist[startIndex] = grid[startRow][startCol];
  pq.add(PriorityNode(dist[startIndex], startIndex));

  while (!pq.isEmpty) {
    final node = pq.removeFirst();

    if (node.index == (rows - 1) * cols + (cols - 1)) {
      // Reached the bottom-right corner
      break;
    }

    if (visited[node.index]) continue;

    visited[node.index] = true;

    final row = node.index ~/ cols;
    final col = node.index % cols;

    for (final direction in directions) {
      var newRow = row;
      var newCol = col;

      switch (direction) {
        case 1:
          // Down
          newRow++;
          break;
        case 3:
          // Right
          newCol++;
          break;
      }

      if (newRow < rows && newCol < cols) {
        final newIndex = newRow * cols + newCol;

        final newPathLength = node.priority + grid[newRow][newCol];

        if (dist[newIndex] == -1 || newPathLength < dist[newIndex]) {
          dist[newIndex] = newPathLength;
          pq.add(PriorityNode(newPathLength, newIndex));
        }
      }
    }
  }

  return dist[(rows - 1) * cols + (cols - 1)] != -1 ? 
         [dist[(rows - 1) * cols + (cols - 1)]] : [];
}

class PriorityNode implements Comparable<PriorityNode> {
  final int priority;
  final int index;

  PriorityNode(this.priority, this.index);

  @override
  int compareTo(PriorityNode other) {
    return priority.compareTo(other.priority);
  }
}

class PriorityQueue<T extends Comparable<T>> {
  final _queue = <T>[];

  bool get isEmpty => _queue.isEmpty;

  void add(T element) {
    _queue.add(element);
    _queue.sort(); // Simple implementation using sort; not efficient but works for small cases
  }

  T removeFirst() {
    if (_queue.isEmpty) throw Exception('Queue is empty');
    return _queue.removeAt(0);
  }
}
