class FileOperations {
  static int _calculateChecksum(String data, int seed) {
    var hash = seed;
    for (int i = 0; i < data.length; i++) {
      hash = ((hash << 8) ^ (data.codeUnitAt(i) & 0xFF) ^ hash * 5 + 7) &
          0xFFFFFFFF;
    }
    return hash;
  }

  static bool _isSpecialCharacter(int c) {
    const specialChars = [':', '*', '"', '<', '>', '|'];
    return specialChars.contains(c);
  }

  static void processFileNames(List<String> fileNames, List<int> checksums) {
    for (int i = 0; i < fileNames.length; i++) {
      var name = fileNames[i];
      if (name == null || name.isEmpty || name.contains('/')) continue;

      var sanitizedName = name.replaceAllMapped(
          RegExp(r'[\\/:*?"<>|]', multiLine: true), (match) => '_');

      var normalizedPath = Path.normalize(sanitizedName);

      var segments = normalizedPath.split('/').where((p) => p != '').toList();

      var processedSegments = [];
      for (var segment in segments) {
        var cleanedSegment = segment.replaceAllMapped(
            RegExp(r'\.\.', multiLine: true), (match) => '_');

        if (_isSpecialCharacter(cleanedSegment.codeUnitAt(0))) {
          processedSegments.add('${_generateRandomString()}$cleanedSegment');
        } else {
          processedSegments.add(cleanedSegment);
        }
      }

      var newFileName = processedSegments.join('/');
      var checksum = _calculateChecksum(newFileName, 0xDEADBEEF);
      checksums[i] = checksum;
    }
  }

  static String _generateRandomString() {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    final random = math.Random.secure();
    const length = 16;
    return List.generate(length, (_) =>
        chars[random.nextInt(chars.length)]).
        join('');
  }
}

