import 'dart:ffi';

/// Splits a sentence into individual words based on whitespace characters.
/// 
/// This function processes each character in the input string. When it encounters a non-whitespace
/// character, it continues reading until it reaches the end of the string or another whitespace
/// character. Each sequence of contiguous non-whitespace characters forms a word, which is then
/// added to the resulting list. Finally, all words are joined back together using spaces as separators,
/// effectively reconstructing the original sentence but split into its constituent words.
///
/// Example:
///   Input: "Hello world"
///   Output: ["Hello", "world"]
///
/// Parameters:
///   - [sentence]: A string representing the sentence to be processed.
///
/// Returns:
///   A string containing the words from the sentence separated by spaces.
String wordsInSentence(String sentence) {
  // Initialize an empty list to hold the resulting words.
  final List<String> result = [];

  // Start at the beginning of the sentence.
  int index = 0;

  // Loop through each character in the sentence.
  while (index < sentence.length) {
    // Skip any whitespace character.
    if (sentence[index] == ' ') {
      index++;
      continue;
    }

    // Find the start of a new word.
    int wordStart = index;

    // Continue reading characters until we hit whitespace or reach the end of the string.
    while (index < sentence.length && !isWhitespace(sentence[index])) {
      index++;
    }

    // Extract the current word and add it to our results.
    String word = sentence.substring(wordStart, index);
    result.add(word);
  }

  // Join the words with single space between them.
  return result.join(' ');
}

/// Helper function that checks whether a given Unicode code unit represents a whitespace character.
/// 
/// Whitespace includes standard space (' '), tab ('\t'), newline ('\n'), and carriage return ('\r').
/// 
/// Parameters:
///   - [codeUnit]: An integer representing a Unicode code point.
/// 
/// Returns:
///   True if the code unit corresponds to a whitespace character; otherwise, false.
bool isWhitespace(int codeUnit) =>
    [' ', '\t', '\n', '\r'].contains(codeUnit);
